let raw = msg.payload;
let d = raw;
let jsonError = false;

// Si viene como texto JSON, convertirlo a objeto
if (typeof d === "string") {
    try {
        d = JSON.parse(d);
    } catch (e) {
        jsonError = true;
        d = {};
    }
}

let estado = d.state || "IDLE";
let puerta = d.door || "CLOSED";
let relay = d.relay_uvc || "OFF";
let restante = Number(d.remaining_s);
let ciclo = Number(d.cycle_s);
let rssi = Number(d.rssi);
let latencia = Number(d.latency_ms);
let comando = d.cmd || d.last_cmd || context.get("ultimoComando") || "NONE";
let msgId = d.msg_id || Date.now();

let wifiStatus = d.wifi_status || "UNKNOWN";
let mqttStatus = d.mqtt_status || "UNKNOWN";
let faultCode = d.fault_code || "NONE";
let faultDetail = d.fault_detail || "Sistema operativo";
let cycleCountEsp = Number(d.cycle_count);

if (isNaN(restante)) restante = 0;
if (isNaN(ciclo)) ciclo = 0;
if (isNaN(rssi)) rssi = -100;
if (isNaN(latencia)) latencia = 0;

let ciclos = context.get("ciclos") || 0;
let estadoAnterior = context.get("estadoAnterior") || "IDLE";

// Si el ESP32 manda contador oficial, usar ese.
// Si no lo manda, mantener contador por transicion RUNNING -> DONE/IDLE.
if (!isNaN(cycleCountEsp)) {
    ciclos = cycleCountEsp;
} else if (estadoAnterior === "RUNNING" && (estado === "DONE" || estado === "IDLE")) {
    ciclos++;
}

context.set("ciclos", ciclos);
context.set("estadoAnterior", estado);
context.set("ultimoComando", comando);

let mqtt = "ONLINE";
let seguridad = "SEGURO";
let alerta = "SIN ALERTAS";

if (jsonError) {
    seguridad = "ERROR";
    alerta = "ERROR JSON";
} else if (faultCode && faultCode !== "NONE") {
    seguridad = "ALERTA";
    alerta = faultCode + " | " + faultDetail;
} else if (puerta === "OPEN" && relay === "ON") {
    seguridad = "CRITICO";
    alerta = "PUERTA ABIERTA CON UV-C ACTIVO";
} else if (puerta === "OPEN") {
    seguridad = "PUERTA ABIERTA";
    alerta = "PUERTA ABIERTA";
} else if (relay === "ON") {
    seguridad = "UV-C ACTIVO";
}else if (estado === "PAUSED") {
    seguridad = "PAUSADO";
    alerta = "Ciclo pausado: presione A para continuar o # para limpiar";
}
if (estado === "ALARM") {
    seguridad = "CRITICO";
}if (estado === "ERROR" || estado === "ERROR_WIFI" || estado === "ERROR_MQTT") {
    seguridad = "ERROR";
}

let evento = new Date().toLocaleString() +
    " | ID: " + msgId +
    " | Estado: " + estado +
    " | Puerta: " + puerta +
    " | UV-C: " + relay +
    " | Ciclo: " + ciclo + " s" +
    " | Restante: " + restante + " s" +
    " | RSSI: " + rssi + " dBm" +
    " | WiFi: " + wifiStatus +
    " | MQTT ESP32: " + mqttStatus +
    " | CMD: " + comando +
    " | Falla: " + faultCode +
    " | Alerta: " + alerta;

return [
    { topic: "estado", payload: estado },
    { topic: "puerta", payload: puerta },
    { topic: "relay_uvc", payload: relay },
    { topic: "restante_s", payload: restante },
    { topic: "rssi", payload: rssi },
    { topic: "seguridad", payload: seguridad },
    { topic: "ciclo_s", payload: ciclo },
    { topic: "evento", payload: evento },
    { topic: "mqtt", payload: mqtt },
    { topic: "ciclos", payload: ciclos },
    { topic: "ultimo_comando", payload: comando },
    { topic: "alerta", payload: alerta },
    { topic: "latencia_ms", payload: latencia },
    { topic: "wifi_status", payload: wifiStatus },
    { topic: "fault_code", payload: faultCode },
    { topic: "fault_detail", payload: faultDetail }
];

let events = msg.payload || [];

msg.payload = events.map(e => {
    return {
        fecha: e.fecha_pc,
        id: e.msg_id,
        estado: e.state,
        puerta: e.door,
        uv: e.relay_uvc,
        rssi: e.rssi,
        wifi: e.wifi_status,
        mqtt: e.mqtt_status,
        falla: e.fault_code,
        cmd: e.last_cmd,
        origen: e.source,
        pdr: e.pdr
    };
});

return msg;

let d = msg.payload;

if (typeof d === "string") {
    try {
        d = JSON.parse(d);
    } catch (e) {
        return null;
    }
}

let now = Date.now();

let msgId = Number(d.msg_id);
let rssi = Number(d.rssi);
let wifi = d.wifi_status || "UNKNOWN";
let mqtt = d.mqtt_status || "UNKNOWN";

let stats = global.get("telecom_stats") || {
    first_id: null,
    last_id: null,
    received: 0,
    lost: 0,
    duplicates: 0,
    seen: {},
    rssi_sum: 0,
    rssi_count: 0,
    rssi_min: null,
    rssi_max: null,
    wifi_down_since: null,
    mqtt_down_since: null,
    wifi_reconnect_last: 0,
    mqtt_reconnect_last: 0,
    wifi_reconnect_total: 0,
    mqtt_reconnect_total: 0,
    wifi_reconnect_count: 0,
    mqtt_reconnect_count: 0,
    events: []
};

// =====================
// PDR por msg_id
// =====================

if (!isNaN(msgId)) {
    if (stats.first_id === null) {
        stats.first_id = msgId;
    }

    if (stats.seen[msgId]) {
        stats.duplicates++;
    } else {
        stats.seen[msgId] = true;
        stats.received++;

        if (stats.last_id !== null && msgId > stats.last_id + 1) {
            stats.lost += msgId - stats.last_id - 1;
        }

        if (stats.last_id === null || msgId > stats.last_id) {
            stats.last_id = msgId;
        }
    }
}

let expected = stats.received + stats.lost;
let pdr = expected > 0 ? (stats.received / expected) * 100 : 100;

// =====================
// RSSI
// =====================

if (!isNaN(rssi) && rssi !== 0) {
    stats.rssi_sum += rssi;
    stats.rssi_count++;

    if (stats.rssi_min === null || rssi < stats.rssi_min) {
        stats.rssi_min = rssi;
    }

    if (stats.rssi_max === null || rssi > stats.rssi_max) {
        stats.rssi_max = rssi;
    }
}

let rssiAvg = stats.rssi_count > 0 ? stats.rssi_sum / stats.rssi_count : 0;

// =====================
// Reconexión WiFi
// =====================

if (wifi !== "CONNECTED" && stats.wifi_down_since === null) {
    stats.wifi_down_since = now;
}

if (wifi === "CONNECTED" && stats.wifi_down_since !== null) {
    let reconnection = now - stats.wifi_down_since;

    stats.wifi_reconnect_last = reconnection;
    stats.wifi_reconnect_total += reconnection;
    stats.wifi_reconnect_count++;

    stats.wifi_down_since = null;
}

// =====================
// Reconexión MQTT
// =====================

if (mqtt !== "CONNECTED" && stats.mqtt_down_since === null) {
    stats.mqtt_down_since = now;
}

if (mqtt === "CONNECTED" && stats.mqtt_down_since !== null) {
    let reconnection = now - stats.mqtt_down_since;

    stats.mqtt_reconnect_last = reconnection;
    stats.mqtt_reconnect_total += reconnection;
    stats.mqtt_reconnect_count++;

    stats.mqtt_down_since = null;
}

let wifiReconnectAvg = stats.wifi_reconnect_count > 0
    ? stats.wifi_reconnect_total / stats.wifi_reconnect_count
    : 0;

let mqttReconnectAvg = stats.mqtt_reconnect_count > 0
    ? stats.mqtt_reconnect_total / stats.mqtt_reconnect_count
    : 0;

// =====================
// Evento para bitácora
// =====================

let event = {
    fecha_pc: new Date(now).toLocaleString(),
    device_id: d.device_id || "",
    fw_version: d.fw_version || "",
    msg_id: d.msg_id || "",
    state: d.state || "",
    door: d.door || "",
    relay_uvc: d.relay_uvc || "",
    cycle_s: d.cycle_s || 0,
    remaining_s: d.remaining_s || 0,
    confirmed_s: d.confirmed_s || 0,
    cycle_count: d.cycle_count || 0,
    rssi: d.rssi || 0,
    wifi_status: d.wifi_status || "",
    mqtt_status: d.mqtt_status || "",
    fault_code: d.fault_code || "",
    fault_detail: d.fault_detail || "",
    last_cmd: d.last_cmd || "",
    source: d.source || "",
    free_heap: d.free_heap || 0,
    esp_ts_ms: d.ts || 0,
    pdr: Number(pdr.toFixed(2))
};

//stats.events.unshift(event);
//stats.events = stats.events.slice(0, 1000);
let eventKey = [
    d.state,
    d.door,
    d.relay_uvc,
    d.fault_code,
    d.last_cmd,
    d.source
].join("|");

let lastEventKey = stats.last_event_key || "";

if (eventKey !== lastEventKey) {
    stats.events.unshift(event);
    stats.events = stats.events.slice(0, 1000);
    stats.last_event_key = eventKey;
}



//////

global.set("telecom_stats", stats);

//////////////////////////
///PRUEBA 1000 MENSAJES///
//////////////////////////

let test = global.get("test_1000");

if (test && test.active) {
    test.current = stats.received;
    test.progress = (stats.received / test.target) * 100;

    if (stats.received >= test.target) {
        test.active = false;
        test.end_time = Date.now();
        test.duration_s = (test.end_time - test.start_time) / 1000;
    }

    global.set("test_1000", test);
}

//////////////////////////
///CALIDAD DE LA SEÑAL///
//////////////////////////

let calidadRSSI = "CRÍTICA";

if (rssiAvg >= -60) {
    calidadRSSI = "BUENA";
} else if (rssiAvg >= -70) {
    calidadRSSI = "ACEPTABLE";
} else if (rssiAvg >= -80) {
    calidadRSSI = "DÉBIL";
} else {
    calidadRSSI = "CRÍTICA";
}

let rssiEstado =
    rssi >= -70 ? "ok" :
    rssi >= -80 ? "warn" :
    "bad";

let estadoEnlace = "OK";

if (wifi !== "CONNECTED" || mqtt !== "CONNECTED") {
    estadoEnlace = "FALLA";
} else if (rssiAvg < -80) {
    estadoEnlace = "DÉBIL";
}


return [
    {
        payload: {
            titulo: "PDR",
            valor: pdr.toFixed(2) + " %",
            subtitulo: "Packet Delivery Ratio",
            estado: pdr >= 98 ? "ok" : pdr >= 95 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "Recibidos",
            valor: stats.received,
            subtitulo: "Mensajes MQTT",
            estado: "ok"
        }
    },
    {
        payload: {
