            estado: stats.lost === 0 ? "ok" : stats.lost <= 5 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "Duplicados",
            valor: stats.duplicates,
            subtitulo: "Mensajes repetidos",
            estado: stats.duplicates === 0 ? "ok" : "warn"
        }
    },
    { payload: rssi },
    {
        payload: {
            titulo: "RSSI Prom.",
            valor: rssiAvg.toFixed(1) + " dBm",
            subtitulo: "Promedio señal",
            estado: rssiAvg >= -70 ? "ok" : rssiAvg >= -80 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "RSSI Mín.",
            valor: stats.rssi_min + " dBm",
            subtitulo: "Peor lectura",
            estado: stats.rssi_min >= -70 ? "ok" : stats.rssi_min >= -80 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "RSSI Máx.",
            valor: stats.rssi_max + " dBm",
            subtitulo: "Mejor lectura",
            estado: stats.rssi_max >= -70 ? "ok" : stats.rssi_max >= -80 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "WiFi",
            valor: (wifiReconnectAvg / 1000).toFixed(2) + " s",
            subtitulo: "Reconexión promedio",
            estado: wifiReconnectAvg <= 10000 ? "ok" : wifiReconnectAvg <= 30000 ? "warn" : "bad"
        }
    },
    { payload: stats.events },
    {
        payload: {
            titulo: "MQTT",
            valor: (mqttReconnectAvg / 1000).toFixed(2) + " s",
            subtitulo: "Reconexión promedio",
            estado: mqttReconnectAvg <= 5000 ? "ok" : mqttReconnectAvg <= 15000 ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "Calidad",
            valor: calidadRSSI,
            subtitulo: "Umbral crítico -80 dBm",
            estado: calidadRSSI === "BUENA" ? "ok" : calidadRSSI === "ACEPTABLE" || calidadRSSI === "DÉBIL" ? "warn" : "bad"
        }
    },
    {
        payload: {
            titulo: "RSSI Actual",
            valor: rssi + " dBm",
            subtitulo: "Última telemetría",
            estado: rssiEstado
        }
    },
    {
        payload: {
            titulo: "Enlace",
            valor: estadoEnlace,
            subtitulo: "WiFi + MQTT",
            estado: estadoEnlace === "OK" ? "ok" : estadoEnlace === "DÉBIL" ? "warn" : "bad"
        }
    }
];

