let key = String(msg.payload || "").trim();

let buffer = flow.get("keypad_buffer") || "";
let confirmed = flow.get("cycle_s") || 0;

let status = "";
const maxDigits = 5;
const maxCycle = 10000;

let mqttMsg = {
    topic: "/cabina_uvc/cmd",
    payload: JSON.stringify({
        cmd: "KEY",
        key: key,
        source: "dashboard_keypad",
        ts: Date.now()
    })
};

if (/^[0-9]$/.test(key)) {
    if (buffer.length < maxDigits) {
        buffer += key;
    }

    flow.set("keypad_buffer", buffer);
    status = "Entrada: " + buffer + " s";
}

else if (key === "#") {
    buffer = "";
    flow.set("keypad_buffer", "");
    status = "Entrada borrada";
}

else if (key === "*") {
    let value = Number(buffer);

    if (buffer === "" || isNaN(value) || value <= 0) {
        status = "Tiempo invalido";
    } else if (value > maxCycle) {
        status = "Maximo permitido: " + maxCycle + " s";
    } else {
        confirmed = value;
        flow.set("cycle_s", confirmed);
        flow.set("keypad_buffer", "");
        status = "Tiempo confirmado: " + confirmed + " s";
    }
}

else if (key === "A") {
    status = "START enviado";
}

else if (key === "B") {
    status = "STOP enviado";
}

else if (key === "C") {
    flow.set("keypad_buffer", "");
    status = "RESET enviado";
}

else if (key === "D") {
    flow.set("keypad_buffer", "");
    flow.set("cycle_s", 0);
    status = "SAFE RESET enviado";
}

else {
    status = "Tecla no valida: " + key;
}

let displayMsg = {
    payload: status
};

let inputMsg = {
    payload: flow.get("keypad_buffer") || "-"
};

let confirmedMsg = {
    payload: (flow.get("cycle_s") || 0) + " s"
};

let lastKeyMsg = {
    payload: key
};

return [
    mqttMsg,
    displayMsg,
    inputMsg,
    confirmedMsg,
    lastKeyMsg
];

